    std::vector<char> text_in_chars{};
  for (const auto &char_ : text) {
    text_in_chars.push_back(char_);
  }
  for (auto &char_ : text_in_chars) {
    if (char_ == ' ') {
      char_ = '_';
    }
  }
  std::vector<int> count_spaces_in_row{};
  int count_spaces = 0;
  for (int i = 0; i < text_in_chars.size(); ++i) {
