  for (int i = 0; i < count_spaces_in_row.size(); ++i) {
    if (count_spaces_in_row[i] > 2) {
      indexes_for_replacement.push_back(i);
    }
  }
  for (const auto &index : indexes_for_replacement) {
    text_in_chars[index] = '-';
  }
  std::string result{};
  for (const auto &char_ : text_in_chars) {
    result += char_;
  }
  return result;

