    std::stringstream ss(sentence);
    std::vector<std::string> words;
    std::string word;
    while (ss >> word) {
        words.push_back(word);
    }
    // Next we iterate over the vector and find words whose length is a prime number.
    for (const auto& word : words) {
        if (primes.find(word.length()) != primes.end()) {
            // If a word's length is a prime number,
            // we concatenate it to the result string.
            result += (word + " ");
        }
    }
